import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().run();
    }

    void run() {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        TaskG solver = new TaskG();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskG {
        static final int MAX_N = 1 << 21;
        static final double[] cs = new double[MAX_N];
        static final double[] sn = new double[MAX_N];
        static final double[] csi = new double[MAX_N];
        static final double[] sni = new double[MAX_N];

        static {
            for (int i = 0; i < MAX_N; i++) {
                double angle = 2 * Math.PI * i / MAX_N;
                cs[i] = Math.cos(angle);
                sn[i] = Math.sin(angle);
                csi[i] = Math.cos(-angle);
                sni[i] = Math.sin(-angle);
            }
        }

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            final int MOD = 998244353;
            int n = in.nextInt();
            int k = in.nextInt();
            int[] v = new int[10];
            for (int i = 0; i < k; i++) {
                v[in.nextInt()] = 1;
            }
            int[] ans = {1};
            int p = n / 2;
            while (true) {
                if ((p & 1) == 1) {
                    ans = multiplyPolynomial(ans, v, MOD);
                }
                p >>= 1;
                if (p == 0) break;
                v = multiplyPolynomial(v, v, MOD);
            }
            long result = 0;
            for (int x : ans) {
                result = (result + (long) x * x) % MOD;
            }
            out.println(result);
        }

        static int[] multiplyPolynomial(int[] a, int[] b, int mod) {
            int need = a.length + b.length - 1;
            int n = Math.max(2, Integer.highestOneBit(need - 1) << 1);

            double[] aReal = new double[n];
            double[] aImag = new double[n];
            for (int i = 0; i < a.length; i++) {
                int val = ((a[i] % mod) + mod) % mod;
                aReal[i] = val & 0x7FFF;
                aImag[i] = val >>> 15;
            }
            performFFT(aReal, aImag, false);

            double[] bReal = new double[n];
            double[] bImag = new double[n];
            for (int i = 0; i < b.length; i++) {
                int val = ((b[i] % mod) + mod) % mod;
                bReal[i] = val & 0x7FFF;
                bImag[i] = val >>> 15;
            }
            performFFT(bReal, bImag, false);

            double[] resReal1 = new double[n];
            double[] resImag1 = new double[n];
            double[] resReal2 = new double[n];
            double[] resImag2 = new double[n];

            for (int i = 0; i < n; i++) {
                int j = (n - i) & (n - 1);

                double ar1 = (aReal[i] + aReal[j]) * 0.5;
                double ai1 = (aImag[i] - aImag[j]) * 0.5;
                double ar2 = (aImag[i] + aImag[j]) * 0.5;
                double ai2 = (aReal[j] - aReal[i]) * 0.5;

                double br1 = (bReal[i] + bReal[j]) * 0.5;
                double bi1 = (bImag[i] - bImag[j]) * 0.5;
                double br2 = (bImag[i] + bImag[j]) * 0.5;
                double bi2 = (bReal[j] - bReal[i]) * 0.5;

                resReal1[i] = ar1 * br1 - ai1 * bi1 - ar2 * bi2 - ai2 * br2;
                resImag1[i] = ar1 * bi1 + ai1 * br1 + ar2 * br2 - ai2 * bi2;
                resReal2[i] = ar1 * br2 - ai1 * bi2 + ar2 * br1 - ai2 * bi1;
                resImag2[i] = ar1 * bi2 + ai1 * br2 + ar2 * bi1 + ai2 * br1;
            }

            performFFT(resReal1, resImag1, true);
            performFFT(resReal2, resImag2, true);

            int[] result = new int[need];
            for (int i = 0; i < need; i++) {
                long aa = Math.round(resReal1[i]);
                long bb = Math.round(resReal2[i]);
                long cc = Math.round(resImag1[i]);
                result[i] = (int) ((aa + ((bb % mod) << 15) + ((cc % mod) << 30)) % mod);
            }
            return result;
        }

        static void performFFT(double[] re, double[] im, boolean inverse) {
            int n = re.length;
            int shift = 32 - Integer.numberOfTrailingZeros(n);
            for (int i = 1; i < n; i++) {
                int j = Integer.reverse(i << shift);
                if (i < j) {
                    double tmp = re[i]; re[i] = re[j]; re[j] = tmp;
                    tmp = im[i]; im[i] = im[j]; im[j] = tmp;
                }
            }

            for (int len = 2; len <= n; len <<= 1) {
                int half = len >> 1;
                int step = cs.length / len;
                for (int i = 0; i < n; i += len) {
                    for (int j = 0, w = 0; j < half; j++, w += step) {
                        double wr = inverse ? csi[w] : cs[w];
                        double wi = inverse ? sni[w] : sn[w];
                        double x = re[i + j + half] * wr - im[i + j + half] * wi;
                        double y = re[i + j + half] * wi + im[i + j + half] * wr;
                        re[i + j + half] = re[i + j] - x;
                        im[i + j + half] = im[i + j] - y;
                        re[i + j] += x;
                        im[i + j] += y;
                    }
                }
            }

            if (inverse) {
                double invN = 1.0 / n;
                for (int i = 0; i < n; i++) {
                    re[i] *= invN;
                    im[i] *= invN;
                }
            }
        }
    }

    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int len = 0;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (len == -1) throw new InputMismatchException();
            if (ptr >= len) {
                ptr = 0;
                try {
                    len = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (len <= 0) return -1;
            }
            return buffer[ptr++] & 0xFF;
        }

        public int nextInt() {
            int c = read();
            while (isSpace(c)) c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                val = val * 10 + c - '0';
                c = read();
            } while (!isSpace(c));
            return val * sign;
        }

        private boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
